import React, { useEffect, useState } from 'react';
import api from '../api';
import BookCard from '../components/BookCard';

export default function Home(){
  const [books, setBooks] = useState([]);
  const [q, setQ] = useState('');
  const [page, setPage] = useState(1);
  const [pages, setPages] = useState(1);
  const [loading, setLoading] = useState(false);

  async function loadBooks(p=1){
    setLoading(true);
    try {
      const res = await api.get(`/api/books?q=${encodeURIComponent(q)}&page=${p}&limit=12`);
      setBooks(res.data.data);
      setPage(res.data.page);
      setPages(res.data.pages);
    } catch(err){ alert(err?.response?.data?.message || err.message); } finally { setLoading(false); }
  }

  useEffect(()=>{ loadBooks(1); }, []);

  return (
    <div>
      <div className="bg-gradient-to-r from-blue-600 to-indigo-600 rounded-lg p-8 text-white mb-6">
        <h1 className="text-4xl font-bold">Find your next great read</h1>
        <p className="mt-2">Featured, bestsellers and new arrivals — curated for you.</p>
        <div className="mt-4 flex gap-2">
          <input value={q} onChange={(e)=>setQ(e.target.value)} placeholder="Search by title or author..." className="w-full max-w-lg p-3 rounded" />
          <button onClick={()=>loadBooks(1)} className="bg-white text-blue-600 px-4 rounded">Search</button>
        </div>
      </div>

      {loading ? <div>Loading...</div> : (
        <>
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
            {books.map(b=> <BookCard key={b._id} book={b} />)}
          </div>

          <div className="mt-6 flex justify-center items-center gap-3">
            <button onClick={()=>loadBooks(Math.max(1,page-1))} className="px-3 py-1 bg-white rounded shadow">Prev</button>
            <span>Page {page} / {pages}</span>
            <button onClick={()=>loadBooks(Math.min(pages,page+1))} className="px-3 py-1 bg-white rounded shadow">Next</button>
          </div>
        </>
      )}
    </div>
  );
}
